INSERT INTO `ai_interaction_logs` (`id`, `cost`, `created_at`, `error_message`, `input_tokens`, `interaction_type`, `latency_ms`, `lesson_id`, `model`, `output_tokens`, `prompt`, `response`, `status`, `total_tokens`, `user_id`) VALUES
('2288ce65-7d36-422f-bd29-6139c9170c19', NULL, '2026-05-13 09:37:37.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"I goes\",\n      \"correct\": \"I went\",\n      \"explanation\": \"Sử dụng động từ đúng theo thì quá khứ\",\n      \"rule\": \"Thì quá khứ đơn: Sử dụng động từ chính ở dạng quá khứ (V2) với chủ ngữ I, you, he, she, it, we, they\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"yesterday\",\n      \"correct\": \"yesterday\",\n      \"explanation\": \"Không cần sửa, nhưng cần kết hợp với thì quá khứ\",\n      \"rule\": \"Thì quá khứ đơn: Sử dụng để mô tả hành động xảy ra và kết thúc trong quá khứ\"\n    }\n  ],\n  \"betterExpression\": \"I attended school yesterday\",\n  \"tip\": \"Học cách sử dụng thì quá khứ đơn và các động từ thường sử dụng trong thì này\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
('3973e53f-00b8-4dc4-860b-f2f2f79b1aa1', NULL, '2026-05-13 09:32:30.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"goes\",\n      \"correct\": \"went\",\n      \"explanation\": \"Sử dụng thì quá khứ cho động từ \'go\'\",\n      \"rule\": \"Quy tắc sử dụng thì quá khứ đơn (past simple) cho hành động xảy ra trong quá khứ\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"I goes\",\n      \"correct\": \"I went\",\n      \"explanation\": \"Sử dụng chủ ngữ \'I\' với động từ \'went\' trong thì quá khứ\",\n      \"rule\": \"Quy tắc sử dụng động từ trong thì quá khứ đơn (past simple) với chủ ngữ \'I\'\"\n    }\n  ],\n  \"betterExpression\": \"I went to school yesterday\",\n  \"tip\": \"Hãy nhớ sử dụng thì quá khứ đơn (past simple) cho hành động xảy ra trong quá khứ và sử dụng đúng dạng động từ cho chủ ngữ \'I\'\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
('4e01485b-8e05-4e2c-89b0-7e8e820631e8', NULL, '2026-05-13 09:37:35.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"goes\",\n      \"correct\": \"went\",\n      \"explanation\": \"Sử dụng động từ đúng dạng quá khứ\",\n      \"rule\": \"Quy tắc sử dụng thì quá khứ đơn\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"yesterday\",\n      \"correct\": \"yesterday\",\n      \"explanation\": \"Không có lỗi, nhưng cần kết hợp với động từ đúng dạng\",\n      \"rule\": \"Quy tắc sử dụng thì quá khứ đơn\"\n    }\n  ],\n  \"betterExpression\": \"I attended school yesterday\",\n  \"tip\": \"Học cách sử dụng các thì trong tiếng Anh, đặc biệt là thì quá khứ đơn để diễn đạt hành động đã xảy ra trong quá khứ\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
('7bae5119-d8c4-4560-840c-f0481b9073aa', NULL, '2026-05-13 09:32:27.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"goes\",\n      \"correct\": \"went\",\n      \"explanation\": \"Sai động từ\",\n      \"rule\": \"Quy tắc sử dụng động từ trong quá khứ\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"yesterday\",\n      \"correct\": \"yesterday\",\n      \"explanation\": \"Đúng nhưng cần kết hợp với động từ đúng\",\n      \"rule\": \"Quy tắc sử dụng trạng từ chỉ thời gian\"\n    }\n  ],\n  \"betterExpression\": \"I attended school yesterday\",\n  \"tip\": \"Học cách sử dụng động từ trong quá khứ và hiện tại\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
('8020cb76-0f78-4d98-8bc8-55f9c10e39cc', NULL, '2026-05-13 09:37:28.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"I goes\",\n      \"correct\": \"I went\",\n      \"explanation\": \"Sử dụng thì quá khứ để chỉ hành động đã xảy ra trong quá khứ\",\n      \"rule\": \"Thì quá khứ của động từ \'go\' là \'went\'\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"yesterday\",\n      \"correct\": \"yesterday\",\n      \"explanation\": \"Không cần sửa, nhưng cần kết hợp với thì quá khứ\",\n      \"rule\": \"Thì quá khứ thường được sử dụng với các từ chỉ thời gian như \'yesterday\', \'last week\', \'last year\'\"\n    }\n  ],\n  \"betterExpression\": \"I went to school the day before today\",\n  \"tip\": \"Học cách sử dụng thì quá khứ để mô tả các hành động đã xảy ra trong quá khứ và kết hợp với các từ chỉ thời gian như \'yesterday\', \'last week\', \'last year\'\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
