('a0d5d194-da76-419f-8c33-752e96cea204', NULL, '2026-05-13 09:37:39.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"goes\",\n      \"correct\": \"went\",\n      \"explanation\": \"Sử dụng thì quá khứ\",\n      \"rule\": \"Thì quá khứ đơn được sử dụng để diễn tả hành động đã xảy ra trong quá khứ\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"I goes\",\n      \"correct\": \"I went\",\n      \"explanation\": \"Sự đồng nhất về chủ ngữ và động từ\",\n      \"rule\": \"Chủ ngữ \'I\' cần được sử dụng với động từ \'went\' trong thì quá khứ\"\n    }\n  ],\n  \"betterExpression\": \"I attended school yesterday\",\n  \"tip\": \"Lưu ý sử dụng đúng thì quá khứ khi nói về hành động đã xảy ra trong quá khứ\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
('c2bd89ae-8899-4f55-aa8f-d02f572fcc59', NULL, '2026-05-13 09:37:30.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"goes\",\n      \"correct\": \"went\",\n      \"explanation\": \"Sử dụng động từ đúng thời gian quá khứ\",\n      \"rule\": \"Quy tắc sử dụng thì quá khứ đơn (Simple Past) với động từ chính\"\n    },\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"yesterday\",\n      \"correct\": \"yesterday\",\n      \"explanation\": \"Không có lỗi về từ \'yesterday\', nhưng cần kết hợp với thì quá khứ\",\n      \"rule\": \"Sử dụng từ chỉ thời gian phù hợp với thì đang sử dụng\"\n    }\n  ],\n  \"betterExpression\": \"I attended school yesterday\",\n  \"tip\": \"Hãy nhớ sử dụng thì quá khứ đơn (Simple Past) khi nói về hành động xảy ra vào một thời điểm cụ thể trong quá khứ.\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
