('e2914abc-df36-40db-b9d0-eae07b29a733', NULL, '2026-05-13 09:37:26.000000', NULL, 0, 'GRAMMAR_CHECK', NULL, NULL, 'llama-3.3-70b-versatile', 0, 'I goes to school yesterday', '{\n  \"original\": \"I goes to school yesterday\",\n  \"corrected\": \"I went to school yesterday\",\n  \"isCorrect\": false,\n  \"errors\": [\n    {\n      \"type\": \"GRAMMAR\",\n      \"wrong\": \"goes\",\n      \"correct\": \"went\",\n      \"explanation\": \"Sử dụng đúng thì quá khứ của động từ \'go\'\",\n      \"rule\": \"Quy tắc sử dụng thì quá khứ đơn (Simple Past) để diễn tả hành động xảy ra trong quá khứ\"\n    }\n  ],\n  \"betterExpression\": \"I went to school yesterday\",\n  \"tip\": \"Hãy nhớ rằng động từ \'go\' có thì quá khứ là \'went\', và sử dụng đúng thì để tránh sai sót ngữ pháp\"\n}', 'SUCCESS', 0, '425dab6e-550b-442d-8567-f2f1311b2ff2'),
