INSERT INTO `exercises` (`id`, `created_at`, `order_index`, `points`, `question_data`, `time_limit_seconds`, `title`, `type`, `lesson_id`) VALUES
('0035e9fe-f683-4519-b64c-521f751aedb2', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[{\"left\":\"Как пройти?\",\"right\":\"Di theo duong nao?\"},{\"left\":\"Это далеко?\",\"right\":\"Day co xa khong?\"},{\"left\":\"Покажите на карте\",\"right\":\"Chi tren ban do\"},{\"left\":\"Спасибо за помощь\",\"right\":\"Cam on su giup do\"}],\"explanation\":\"Những câu hỏi đường phổ biến trong tiếng Nga.\"}', 30, 'Nối câu hỏi đường', 'MATCHING', 'e4e19005-4952-11f1-a796-e00af6a25786'),
('00c4d7a1-32e0-44bb-8c40-cdfcb3761d4a', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"\\\"Один\\\" trong tiếng Nga nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Mot\",\"hints\":[\"number\"],\"explanation\":\"Один = Một (1). Два = Hai (2).\"}', 20, 'Điền: Один = _____', 'FILL_IN_BLANK', 'e4dd6e3c-4952-11f1-a796-e00af6a25786'),
('010fc6ea-6e52-47f9-81f3-200333ed2bbb', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"\\\"Vou viajar amanhã\\\" trong tiếng Bồ Đào Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Toi se di du lich ngay mai\",\"hints\":[\"future\"],\"explanation\":\"Vou = Sẽ / Sắp (tương lai gần). viajar = Đi du lịch. amanhã = Ngày mai.\"}', 20, 'Điền: Vou viajar = _____', 'FILL_IN_BLANK', 'e4e47f3c-4952-11f1-a796-e00af6a25786'),
