('bb219943-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"How do you form Konjunktiv II of regular verbs?\",\"options\":[\"verb + te + en\",\"Stem + te + en\",\"haben/waren + past participle\",\"wurde + infinitive\"],\"correctIndex\":1,\"explanation\":\"Konjunktiv II: Stem + te + en. E.g., ware, hatte, konnte.\"}', 20, 'How to form Konjunktiv II?', 'MULTIPLE_CHOICE', 'e4cd4fa1-4952-11f1-a796-e00af6a25786'),
('bb21a2f3-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Wenn ich Geld _____, wurde ich reisen. If I had money, I would travel. (hatte)\",\"answer\":\"hatte\",\"hints\":[\"Konjunktiv II\"],\"explanation\":\"Konjunktiv II: ich hatte = I would have.\"}', 15, 'Fill in: Wenn ich Geld _____, wurde ich reisen', 'FILL_IN_BLANK', 'e4cd4fa1-4952-11f1-a796-e00af6a25786'),
('bb21a5c7-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Ware\",\"right\":\"I would be\"},{\"left\":\"Hatte\",\"right\":\"I would have\"},{\"left\":\"Konnte\",\"right\":\"I could\"},{\"left\":\"Wurde\",\"right\":\"I would become\"}]}', 30, 'Match Konjunktiv II forms', 'MATCHING', 'e4cd4fa1-4952-11f1-a796-e00af6a25786'),
('bb21a6f2-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"What is the Konjunktiv II of sein?\",\"options\":[\"Sein\",\"War\",\"Ware\",\"Wurde\"],\"correctIndex\":2,\"explanation\":\"Ware = Konjunktiv II of sein.\"}', 15, 'Konjunktiv II of sein?', 'MULTIPLE_CHOICE', 'e4cd4fa1-4952-11f1-a796-e00af6a25786'),
('bb21a7f6-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Ich _____ gern Deutscher. I would like to be German. (ware)\",\"answer\":\"ware\",\"hints\":[\"Konjunktiv II of sein\"],\"explanation\":\"ware = would be (Konjunktiv II).\"}', 15, 'Fill in: Ich _____ gern Deutscher', 'FILL_IN_BLANK', 'e4cd4fa1-4952-11f1-a796-e00af6a25786'),
('bb227802-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"In a Nebensatz (subordinate clause), where does the verb go?\",\"options\":[\"At the end\",\"At the beginning\",\"In the middle\",\"After the subject\"],\"correctIndex\":0,\"explanation\":\"In Nebensatze, the verb goes at the end of the clause.\"}', 20, 'What does weil clause need?', 'MULTIPLE_CHOICE', 'e4cd5288-4952-11f1-a796-e00af6a25786'),
('bb2281d5-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"_____ ich krank bin, gehe ich zum Arzt. Because I am sick, I go to the doctor. (Weil)\",\"answer\":\"Weil\",\"hints\":[\"because\"],\"explanation\":\"Weil introduces a Nebensatz with verb at the end: weil ich krank bin.\"}', 15, 'Fill in: _____ ich krank bin, gehe ich zum Arzt', 'FILL_IN_BLANK', 'e4cd5288-4952-11f1-a796-e00af6a25786'),
('bb228359-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Weil\",\"right\":\"Because\"},{\"left\":\"Obwohl\",\"right\":\"Although\"},{\"left\":\"Dass\",\"right\":\"That\"},{\"left\":\"Wenn\",\"right\":\"If/When\"}]}', 30, 'Match subordinating conjunctions', 'MATCHING', 'e4cd5288-4952-11f1-a796-e00af6a25786'),
('bb22848a-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"In a Nebensatz introduced by obwohl, where is the verb?\",\"options\":[\"At the beginning\",\"At the end\",\"After the conjunction\",\"Before the subject\"],\"correctIndex\":1,\"explanation\":\"Verb at the end of the Nebensatz: obwohl ich很累 bin.\"}', 15, 'Verb position in Nebensatz?', 'MULTIPLE_CHOICE', 'e4cd5288-4952-11f1-a796-e00af6a25786'),
('bb22859e-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Er kam nicht, _____ er krank war. He did not come because he was sick. (obwohl)\",\"answer\":\"obwohl\",\"hints\":[\"although\"],\"explanation\":\"obwohl = although/even though.\"}', 15, 'Fill in: Er kam nicht, _____ er krank war', 'FILL_IN_BLANK', 'e4cd5288-4952-11f1-a796-e00af6a25786'),
('bb24018a-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"A standard German essay has how many parts?\",\"options\":[\"2 parts\",\"3 parts\",\"4 parts\",\"5 parts\"],\"correctIndex\":1,\"explanation\":\"Standard German essay: Einleitung (introduction), Hauptteil (body), Schluss (conclusion) = 3 parts.\"}', 20, 'Essay structure?', 'MULTIPLE_CHOICE', 'e4cd52f1-4952-11f1-a796-e00af6a25786'),
('bb240b3a-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Die _____ (Einleitung) in German means the introduction in English.\",\"answer\":\"Einleitung\",\"hints\":[\"beginning\"],\"explanation\":\"Die Einleitung = the introduction.\"}', 15, 'Fill in: Die _____ = the introduction', 'FILL_IN_BLANK', 'e4cd52f1-4952-11f1-a796-e00af6a25786'),
('bb240c78-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Die Einleitung\",\"right\":\"Introduction\"},{\"left\":\"Der Hauptteil\",\"right\":\"Main body\"},{\"left\":\"Der Schluss\",\"right\":\"Conclusion\"},{\"left\":\"Das Fazit\",\"right\":\"Final remark\"}]}', 30, 'Match essay parts', 'MATCHING', 'e4cd52f1-4952-11f1-a796-e00af6a25786'),
('bb240d9b-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Der Schluss means:\",\"options\":[\"Introduction\",\"Main body\",\"Conclusion\",\"Summary only\"],\"correctIndex\":2,\"explanation\":\"Der Schluss = the conclusion.\"}', 15, 'What does der Schluss mean?', 'MULTIPLE_CHOICE', 'e4cd52f1-4952-11f1-a796-e00af6a25786'),
('bb240e28-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Im _____ sollte man zusammenfassen. In the conclusion one should summarize. (Schluss)\",\"answer\":\"Schluss\",\"hints\":[\"end\"],\"explanation\":\"Der Schluss = the conclusion.\"}', 15, 'Fill in: Im _____ sollte man zusammenfassen', 'FILL_IN_BLANK', 'e4cd52f1-4952-11f1-a796-e00af6a25786'),
('bb24cb97-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"Was ist los means:\",\"options\":[\"What is wrong\",\"Where is it\",\"What is going on\",\"Who is there\"],\"correctIndex\":2,\"explanation\":\"Was ist los? = What is going on? / What is wrong?\"}', 15, 'Was ist los means?', 'MULTIPLE_CHOICE', 'e4cd5347-4952-11f1-a796-e00af6a25786'),
('bb24d086-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Es _____ mir gut. It is going well with me. (geht)\",\"answer\":\"geht\",\"hints\":[\"go\"],\"explanation\":\"Es geht mir gut = I am doing well.\"}', 15, 'Fill in: Es _____ mir gut', 'FILL_IN_BLANK', 'e4cd5347-4952-11f1-a796-e00af6a25786'),
('bb24d35f-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Was ist los?\",\"right\":\"What is going on?\"},{\"left\":\"Es geht mir gut\",\"right\":\"I am doing well\"},{\"left\":\"Das ist mir egal\",\"right\":\"I dont care\"},{\"left\":\"Ich habe keine Ahnung\",\"right\":\"I have no idea\"}]}', 30, 'Match idioms', 'MATCHING', 'e4cd5347-4952-11f1-a796-e00af6a25786'),
('bb24d41b-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Ich habe keine Ahnung means:\",\"options\":[\"I dont know well\",\"I have no idea\",\"I think so\",\"I am not sure\"],\"correctIndex\":1,\"explanation\":\"Ich habe keine Ahnung = I have no idea.\"}', 15, 'What does ich habe keine Ahnung mean?', 'MULTIPLE_CHOICE', 'e4cd5347-4952-11f1-a796-e00af6a25786'),
('bb24d4aa-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Das ist mir _____. I dont care. (egal)\",\"answer\":\"egal\",\"hints\":[\"same\"],\"explanation\":\"egal = the same (used idiomatically as I dont care).\"}', 15, 'Fill in: Das ist mir _____', 'FILL_IN_BLANK', 'e4cd5347-4952-11f1-a796-e00af6a25786'),
('bb259afd-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"How do you introduce an argument in German formal debate?\",\"options\":[\"Ich finde\",\"Einerseits...andererseits\",\"Das ist falsch\",\"Ich weiss nicht\"],\"correctIndex\":1,\"explanation\":\"Einerseits...andererseits = on one hand...on the other hand.\"}', 20, 'How to introduce argument?', 'MULTIPLE_CHOICE', 'e4cd5398-4952-11f1-a796-e00af6a25786'),
('bb25a42b-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"In einer Debatte _____ man argumentieren. In a debate one should argue. (sollte)\",\"answer\":\"sollte\",\"hints\":[\"should\"],\"explanation\":\"sollte = should (Konjunktiv II of sollen).\"}', 15, 'Fill in: _____ sollte man argumentieren', 'FILL_IN_BLANK', 'e4cd5398-4952-11f1-a796-e00af6a25786'),
('bb25a516-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Einerseits\",\"right\":\"On one hand\"},{\"left\":\"Andererseits\",\"right\":\"On the other hand\"},{\"left\":\"Daher\",\"right\":\"Therefore\"},{\"left\":\"Zusammenfassend\",\"right\":\"In summary\"}]}', 30, 'Match debate words', 'MATCHING', 'e4cd5398-4952-11f1-a796-e00af6a25786'),
('bb25a5a8-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Daher means:\",\"options\":[\"However\",\"Therefore\",\"Because\",\"Moreover\"],\"correctIndex\":1,\"explanation\":\"Daher = therefore/consequently.\"}', 15, 'What does daher mean?', 'MULTIPLE_CHOICE', 'e4cd5398-4952-11f1-a796-e00af6a25786'),
('bb25a626-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"_____fassend lasse ich mich sagen... In conclusion, let me say... (zu)\",\"answer\":\"Zusammen\",\"hints\":[\"together\"],\"explanation\":\"Zusammenfassend = in summary.\"}', 15, 'Fill in: _____fassend lasse ich mich sagen', 'FILL_IN_BLANK', 'e4cd5398-4952-11f1-a796-e00af6a25786'),
('bb26525e-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"How do you greet in German business email?\",\"options\":[\"Hallo Herr Muller\",\"Sehr geehrter Herr Muller\",\"Lieber Herr Muller\",\"Hey Herr Muller\"],\"correctIndex\":1,\"explanation\":\"Sehr geehrter Herr Muller = Dear Mr. Muller (formal).\"}', 20, 'Business German greeting?', 'MULTIPLE_CHOICE', 'e4ce4f78-4952-11f1-a796-e00af6a25786'),
('bb265d40-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Die _____ (Firma) in German business means the company in English.\",\"answer\":\"Firma\",\"hints\":[\"business\"],\"explanation\":\"Die Firma = the company.\"}', 15, 'Fill in: Die _____ = the company', 'FILL_IN_BLANK', 'e4ce4f78-4952-11f1-a796-e00af6a25786'),
('bb265e29-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Die Firma\",\"right\":\"Company\"},{\"left\":\"Der Geschaftspartner\",\"right\":\"Business partner\"},{\"left\":\"Die Besprechung\",\"right\":\"Meeting\"},{\"left\":\"Der Termin\",\"right\":\"Appointment\"}]}', 30, 'Match business words', 'MATCHING', 'e4ce4f78-4952-11f1-a796-e00af6a25786'),
('bb265ed0-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Der Geschaftspartner means:\",\"options\":[\"Customer\",\"Business partner\",\"Employee\",\"Manager\"],\"correctIndex\":1,\"explanation\":\"Der Geschaftspartner = the business partner.\"}', 15, 'What does der Geschaftspartner mean?', 'MULTIPLE_CHOICE', 'e4ce4f78-4952-11f1-a796-e00af6a25786'),
('bb265f51-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Ich mochte einen _____ machen. I would like to make an appointment. (Termin)\",\"answer\":\"Termin\",\"hints\":[\"appointment\"],\"explanation\":\"Der Termin = the appointment.\"}', 15, 'Fill in: Ich mochte einen _____ machen', 'FILL_IN_BLANK', 'e4ce4f78-4952-11f1-a796-e00af6a25786'),
('bb2714fa-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"What is the formal closing in a German business letter?\",\"options\":[\"Viele Grusse\",\"Mit freundlichen Grussen\",\"Liebe Grusse\",\"Tschuss\"],\"correctIndex\":1,\"explanation\":\"Mit freundlichen Grussen = With kind regards (formal).\"}', 20, 'Formal closing?', 'MULTIPLE_CHOICE', 'e4ce5351-4952-11f1-a796-e00af6a25786'),
('bb271ee7-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Sehr geehrte _____ Schmidt, Dear Mrs. Schmidt, (geehrte)\",\"answer\":\"geehrte\",\"hints\":[\"formal\"],\"explanation\":\"Sehr geehrte Frau Schmidt = Dear Mrs. Schmidt (formal).\"}', 15, 'Fill in: _____ Frau Schmidt,', 'FILL_IN_BLANK', 'e4ce5351-4952-11f1-a796-e00af6a25786'),
('bb271fc7-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Sehr geehrte\",\"right\":\"Dear (formal female)\"},{\"left\":\"Sehr geehrter\",\"right\":\"Dear (formal male)\"},{\"left\":\"Mit freundlichen Grussen\",\"right\":\"With kind regards\"},{\"left\":\"Hochachtungsvoll\",\"right\":\"Yours faithfully\"}]}', 30, 'Match letter phrases', 'MATCHING', 'e4ce5351-4952-11f1-a796-e00af6a25786'),
('bb27205b-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Anrede (die Anrede) in a letter means:\",\"options\":[\"Closing\",\"Salutation/Greeting\",\"Signature\",\"Date\"],\"correctIndex\":1,\"explanation\":\"Die Anrede = the salutation or greeting in a letter.\"}', 15, 'Anrede =?', 'MULTIPLE_CHOICE', 'e4ce5351-4952-11f1-a796-e00af6a25786'),
('bb2720cf-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Ich _____ Sie auf einen Kaffee ein. I invite you for a coffee. (lade)\",\"answer\":\"lade\",\"hints\":[\"invite\"],\"explanation\":\"einladen = to invite. Ich lade Sie ein.\"}', 15, 'Fill in: Ich _____ Sie auf einen Kaffee ein', 'FILL_IN_BLANK', 'e4ce5351-4952-11f1-a796-e00af6a25786'),
('bb27cacd-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"How do you start a formal meeting in German?\",\"options\":[\"Fangen wir an\",\"Ich begrusse alle Anwesenden\",\"Wir sind vollzahlig\",\"Lasst uns reden\"],\"correctIndex\":1,\"explanation\":\"Ich begrusse alle Anwesenden = I welcome all those present (formal meeting opener).\"}', 20, 'Start meeting?', 'MULTIPLE_CHOICE', 'e4ce5433-4952-11f1-a796-e00af6a25786'),
('bb27de98-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Die _____ (Tagesordnung) in German means the agenda in English.\",\"answer\":\"Tagesordnung\",\"hints\":[\"day order\"],\"explanation\":\"Die Tagesordnung = the agenda.\"}', 15, 'Fill in: Die _____ = the agenda', 'FILL_IN_BLANK', 'e4ce5433-4952-11f1-a796-e00af6a25786'),
('bb27e07f-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Die Tagesordnung\",\"right\":\"Agenda\"},{\"left\":\"Das Protokoll\",\"right\":\"Minutes\"},{\"left\":\"Die Abstimmung\",\"right\":\"Vote\"},{\"left\":\"Der Beschluss\",\"right\":\"Resolution\"}]}', 30, 'Match meeting words', 'MATCHING', 'e4ce5433-4952-11f1-a796-e00af6a25786'),
('bb27e16c-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Das Protokoll in a meeting context means:\",\"options\":[\"The agenda\",\"The minutes\",\"The vote\",\"The resolution\"],\"correctIndex\":1,\"explanation\":\"Das Protokoll = the minutes (written record of a meeting).\"}', 15, 'What does das Protokoll mean?', 'MULTIPLE_CHOICE', 'e4ce5433-4952-11f1-a796-e00af6a25786'),
('bb27e207-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Gibt es _____ zu diesem Thema? Are there any questions on this topic? (Fragen)\",\"answer\":\"Fragen\",\"hints\":[\"questions\"],\"explanation\":\"Fragen = questions. Gibt es Fragen? = Are there questions?\"}', 15, 'Fill in: Gibt es _____ zu diesem Thema?', 'FILL_IN_BLANK', 'e4ce5433-4952-11f1-a796-e00af6a25786'),
('bb28ba56-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"How do you say We can offer you 5 percent discount in German?\",\"options\":[\"Wir bieten funf Prozent Rabatt\",\"Wir mochten funf Prozent\",\"Wir haben funf Prozent\",\"Wir geben funf Prozent\"],\"correctIndex\":0,\"explanation\":\"Wir bieten = we offer. Wir konnen Ihnen funf Prozent Rabatt anbieten.\"}', 20, 'How to make an offer?', 'MULTIPLE_CHOICE', 'e4ce9813-4952-11f1-a796-e00af6a25786'),
('bb28c4ca-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Der _____ (Preis) in German business means the price in English.\",\"answer\":\"Preis\",\"hints\":[\"cost\"],\"explanation\":\"Der Preis = the price.\"}', 15, 'Fill in: Der _____ = the price', 'FILL_IN_BLANK', 'e4ce9813-4952-11f1-a796-e00af6a25786'),
('bb28c5bf-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Anbieten\",\"right\":\"To offer\"},{\"left\":\"Verhandeln\",\"right\":\"To negotiate\"},{\"left\":\"Der Rabatt\",\"right\":\"The discount\"},{\"left\":\"Der Vertrag\",\"right\":\"The contract\"}]}', 30, 'Match negotiation words', 'MATCHING', 'e4ce9813-4952-11f1-a796-e00af6a25786'),
('bb28c662-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 4, 10, '{\"question\":\"Der Vertrag means:\",\"options\":[\"Price\",\"Contract\",\"Discount\",\"Offer\"],\"correctIndex\":1,\"explanation\":\"Der Vertrag = the contract.\"}', 15, 'What does der Vertrag mean?', 'MULTIPLE_CHOICE', 'e4ce9813-4952-11f1-a796-e00af6a25786');
INSERT INTO `exercises` (`id`, `created_at`, `order_index`, `points`, `question_data`, `time_limit_seconds`, `title`, `type`, `lesson_id`) VALUES
('bb28c7c7-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 5, 10, '{\"question\":\"Wir _____ diesen Preis nicht akzeptieren. We cannot accept this price. (konnen)\",\"answer\":\"konnen\",\"hints\":[\"can\"],\"explanation\":\"konnen = can. Wir konnen diesen Preis nicht akzeptieren.\"}', 15, 'Fill in: Wir _____ diesen Preis nicht', 'FILL_IN_BLANK', 'e4ce9813-4952-11f1-a796-e00af6a25786'),
('bb297e87-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 1, 10, '{\"question\":\"How do you say I would like to schedule an appointment in German?\",\"options\":[\"Ich mochte einen Termin verschieben\",\"Ich mochte einen Termin vereinbaren\",\"Ich brauche einen Kalender\",\"Ich habe Zeit\"],\"correctIndex\":1,\"explanation\":\"einen Termin vereinbaren = to schedule an appointment.\"}', 20, 'How to schedule meeting?', 'MULTIPLE_CHOICE', 'e4ce9927-4952-11f1-a796-e00af6a25786'),
('bb298829-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 2, 10, '{\"question\":\"Der _____ (Kalender) in German means the calendar in English.\",\"answer\":\"Kalender\",\"hints\":[\"schedule\"],\"explanation\":\"Der Kalender = the calendar.\"}', 15, 'Fill in: Der _____ = the calendar', 'FILL_IN_BLANK', 'e4ce9927-4952-11f1-a796-e00af6a25786'),
('bb298910-4972-11f1-a796-e00af6a25786', '2026-05-07 00:40:52.000000', 3, 15, '{\"pairs\":[{\"left\":\"Der Kalender\",\"right\":\"Calendar\"},{\"left\":\"Der Schreibtisch\",\"right\":\"Desk\"},{\"left\":\"Die E-Mail\",\"right\":\"Email\"},{\"left\":\"Die Besprechung\",\"right\":\"Meeting\"}]}', 30, 'Match office words', 'MATCHING', 'e4ce9927-4952-11f1-a796-e00af6a25786'),
