('d986409c-0433-474e-800a-798212049776', '2026-05-07 19:40:00.000000', 5, 10, '{\"question\":\"他是我的男朋友 means _____ in English.\",\"answer\":\"He is my boyfriend\",\"hints\":[\"relationship\"],\"explanation\":\"他是我的男朋友 = He is my boyfriend.\"}', 15, 'Fill in: _____ = He is my boyfriend', 'FILL_IN_BLANK', 'e4ab7614-4952-11f1-a796-e00af6a25786'),
('dad56282-773e-48fa-871f-a86f23514f14', '2026-05-07 19:00:00.000000', 2, 10, '{\"question\":\"Nam in Vietnamese means _____ in English.\",\"answer\":\"Five\",\"hints\":[\"number\"],\"explanation\":\"Mot = 1, Hai = 2, Ba = 3, Bon = 4, Nam = 5.\"}', 15, 'Fill in: Nam = _____', 'FILL_IN_BLANK', 'e4db3351-4952-11f1-a796-e00af6a25786'),
('db3e8a3c-a496-4703-9da9-bab38e9795ab', '2026-05-07 19:40:00.000000', 5, 10, '{\"question\":\"我要买 means _____ in English.\",\"answer\":\"I want to buy\",\"hints\":[\"shopping\"],\"explanation\":\"我要买 = I want to buy.\"}', 15, 'Fill in: _____ = I want to buy', 'FILL_IN_BLANK', 'e4ac4afd-4952-11f1-a796-e00af6a25786'),
('db55b7ac-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"Which hiragana character represents the sound ka?\",\"options\":[\"あ\",\"か\",\"さ\",\"な\"],\"correctIndex\":1,\"explanation\":\"か is read as ka.\"}', 20, 'Which hiragana reads as ka?', 'MULTIPLE_CHOICE', 'e4a104b5-4952-11f1-a796-e00af6a25786'),
('db55d12b-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"The hiragana character か is read as _____.\",\"answer\":\"ka\",\"hints\":[\"first syllable of katakata\"],\"explanation\":\"か represents the ka syllable in Hiragana.\"}', 15, 'Fill in: か is read as _____', 'FILL_IN_BLANK', 'e4a104b5-4952-11f1-a796-e00af6a25786'),
('db5a42ba-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"In the sentence Watashi wa Nihonjin desu, what does は (wa) indicate?\",\"options\":[\"Subject marker\",\"Object marker\",\"Topic marker\",\"Verb marker\"],\"correctIndex\":2,\"explanation\":\"は (wa) marks the topic of the sentence, not the subject.\"}', 20, 'What does は indicate?', 'MULTIPLE_CHOICE', 'e4a10ed0-4952-11f1-a796-e00af6a25786'),
('db5a4a87-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"Watashi _____ Nihonjin desu. (topic marker)\",\"answer\":\"wa\",\"hints\":[\"は particle\"],\"explanation\":\"は (wa) marks watashi as the topic of the sentence.\"}', 15, 'Fill in: Watashi _____ Nihonjin desu', 'FILL_IN_BLANK', 'e4a10ed0-4952-11f1-a796-e00af6a25786'),
('db5a4b2d-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"は (wa)\",\"right\":\"Topic marker\"},{\"left\":\"が (ga)\",\"right\":\"Subject marker\"},{\"left\":\"の (no)\",\"right\":\"Possession\"},{\"left\":\"です (desu)\",\"right\":\"Be verb\"}]}', 30, 'Match particles', 'MATCHING', 'e4a10ed0-4952-11f1-a796-e00af6a25786'),
('db5a4b9b-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"Which sentence means I am a student?\",\"options\":[\"Sensei desu\",\"Gakusei desu\",\"Gakusei aru\",\"Nihongo desu\"],\"correctIndex\":1,\"explanation\":\"Gakusei desu means I am a student. Sensei means teacher.\"}', 20, 'Which is correct?', 'MULTIPLE_CHOICE', 'e4a10ed0-4952-11f1-a796-e00af6a25786'),
('db5a4c0d-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"Kore _____ watashi no hon desu. This book is mine. (possession marker)\",\"answer\":\"wa\",\"hints\":[\"は\"],\"explanation\":\"は (wa) marks the topic. The sentence means This is my book.\"}', 15, 'Fill in: Kore _____ watashi no hon desu', 'FILL_IN_BLANK', 'e4a10ed0-4952-11f1-a796-e00af6a25786'),
('db5bb05a-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"What number is ichi (いち)?\",\"options\":[\"0\",\"1\",\"2\",\"3\"],\"correctIndex\":1,\"explanation\":\"ichi (一) means 1 in Japanese.\"}', 15, 'What is \"ichi\" in number?', 'MULTIPLE_CHOICE', 'e4a10f38-4952-11f1-a796-e00af6a25786'),
('db5bc1da-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"_____ is 100 in Japanese. (hyaku)\",\"answer\":\"百\",\"hints\":[\"100\"],\"explanation\":\"百 (hyaku) means 100 in Japanese.\"}', 15, 'Fill in: _____ is 100 in Japanese', 'FILL_IN_BLANK', 'e4a10f38-4952-11f1-a796-e00af6a25786'),
('db5bc2c6-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"一\",\"right\":\"1\"},{\"left\":\"二\",\"right\":\"2\"},{\"left\":\"三\",\"right\":\"3\"},{\"left\":\"十\",\"right\":\"10\"}]}', 30, 'Match numbers to kanji', 'MATCHING', 'e4a10f38-4952-11f1-a796-e00af6a25786'),
('db5bc363-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"Gozen 3-ji means:\",\"options\":[\"3 PM\",\"3 AM\",\"3 minutes\",\"Afternoon\"],\"correctIndex\":0,\"explanation\":\"Gozen means AM/before noon. Gozen 3-ji is 3 AM.\"}', 20, 'What time is \"gozen\"?', 'MULTIPLE_CHOICE', 'e4a10f38-4952-11f1-a796-e00af6a25786'),
('db5bc3f3-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"_____ is Sunday in Japanese. (nichiyoubi)\",\"answer\":\"日曜日\",\"hints\":[\"sun day\"],\"explanation\":\"日曜日 (nichiyoubi) means Sunday.\"}', 15, 'Fill in: _____ is Sunday', 'FILL_IN_BLANK', 'e4a10f38-4952-11f1-a796-e00af6a25786'),
('db5d4310-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"Which kanji means person (hito)?\",\"options\":[\"大\",\"小\",\"人\",\"山\"],\"correctIndex\":2,\"explanation\":\"人 (hito) means person in Japanese.\"}', 15, 'Which kanji means person?', 'MULTIPLE_CHOICE', 'e4a10f8f-4952-11f1-a796-e00af6a25786'),
('db5d4f19-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"_____ means mountain (yama).\",\"answer\":\"山\",\"hints\":[\"mountain\"],\"explanation\":\"山 (yama) is the kanji for mountain.\"}', 15, 'Fill in: _____ means mountain', 'FILL_IN_BLANK', 'e4a10f8f-4952-11f1-a796-e00af6a25786'),
('db5d506b-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"日\",\"right\":\"Day/Sun\"},{\"left\":\"月\",\"right\":\"Month/Moon\"},{\"left\":\"火\",\"right\":\"Fire\"},{\"left\":\"水\",\"right\":\"Water\"}]}', 30, 'Match kanji meanings', 'MATCHING', 'e4a10f8f-4952-11f1-a796-e00af6a25786'),
('db5d511d-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"What does the kanji 木 (ki) mean?\",\"options\":[\"Water\",\"Fire\",\"Tree\",\"Earth\"],\"correctIndex\":2,\"explanation\":\"木 (ki) means tree or wood in Japanese.\"}', 15, 'What does 木 mean?', 'MULTIPLE_CHOICE', 'e4a10f8f-4952-11f1-a796-e00af6a25786'),
('db5d51b0-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"大 (dai/oo) means _____ (small opposite).\",\"answer\":\"big\",\"hints\":[\"large\"],\"explanation\":\"大 means big or large, opposite of 小 (small).\"}', 15, 'Fill in: 大 means _____', 'FILL_IN_BLANK', 'e4a10f8f-4952-11f1-a796-e00af6a25786'),
('db5ec877-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"What does 食べる (taberu) mean?\",\"options\":[\"To drink\",\"To eat\",\"To sleep\",\"To run\"],\"correctIndex\":1,\"explanation\":\"食べる (taberu) means to eat in Japanese.\"}', 15, 'What does 食べる mean?', 'MULTIPLE_CHOICE', 'e4a28acc-4952-11f1-a796-e00af6a25786'),
('db5ed585-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"飲む (nomu) means to _____ (drink).\",\"answer\":\"drink\",\"hints\":[\"opposite of eat\"],\"explanation\":\"飲む (nomu) means to drink in Japanese.\"}', 15, 'Fill in: 飲む means to _____', 'FILL_IN_BLANK', 'e4a28acc-4952-11f1-a796-e00af6a25786'),
('db5ed63a-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"食\",\"right\":\"Eat\"},{\"left\":\"飲\",\"right\":\"Drink\"},{\"left\":\"見\",\"right\":\"See\"},{\"left\":\"聞\",\"right\":\"Hear\"}]}', 30, 'Match N4 kanji', 'MATCHING', 'e4a28acc-4952-11f1-a796-e00af6a25786'),
('db5ed6f0-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"Which kanji means book (hon)?\",\"options\":[\"書く\",\"読む\",\"本\",\"買う\"],\"correctIndex\":2,\"explanation\":\"本 (hon) means book in Japanese.\"}', 15, 'Which kanji means book?', 'MULTIPLE_CHOICE', 'e4a28acc-4952-11f1-a796-e00af6a25786'),
('db5ed75e-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"_____ means to write (kaku).\",\"answer\":\"書く\",\"hints\":[\"write\"],\"explanation\":\"書く (kaku) means to write in Japanese.\"}', 15, 'Fill in: _____ means to write', 'FILL_IN_BLANK', 'e4a28acc-4952-11f1-a796-e00af6a25786'),
('db602e20-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"映画を見えて _____. I watched a movie. (finished)\",\"answer\":\"しました\",\"hints\":[\"past of 見る\"],\"explanation\":\"Visibility te-form + しました shows the action is completed.\"}', 20, 'Fill in: 見て _____ toimasu', 'FILL_IN_BLANK', 'e4a28d3a-4952-11f1-a796-e00af6a25786'),
('db602f31-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"~てください\",\"right\":\"Please do\"},{\"left\":\"~てもいいですか\",\"right\":\"May I do\"},{\"left\":\"~ています\",\"right\":\"Currently doing\"},{\"left\":\"~てくださいました\",\"right\":\"Did for me\"}]}', 30, 'Match te-form uses', 'MATCHING', 'e4a28d3a-4952-11f1-a796-e00af6a25786'),
('db602fea-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"Which is the correct te-form of 飲む (nomu)?\",\"options\":[\"飲みて\",\"飲んで\",\"飲むて\",\"飲みて\"],\"correctIndex\":1,\"explanation\":\"んで group: 飲んで (nonde) is the te-form of 飲む.\"}', 15, 'Which te-form is correct?', 'MULTIPLE_CHOICE', 'e4a28d3a-4952-11f1-a796-e00af6a25786'),
('db603080-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"Please wait here. _____ desu kara kudasai. (this)\",\"answer\":\"ここに\",\"hints\":[\"here\"],\"explanation\":\"ここに (koko ni) means here. ここに Desu kara kudasai means Please be here.\"}', 15, 'Fill in: _____ desu kara kudasai', 'FILL_IN_BLANK', 'e4a28d3a-4952-11f1-a796-e00af6a25786'),
('db61bade-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"Watashi wa Nihongo ga _____. I can speak Japanese. (speak)\",\"answer\":\"話せます\",\"hints\":[\"can speak\"],\"explanation\":\"話せます (hanasemasu) is the potential form of 話す.\"}', 20, 'Fill in: Watashi wa Nihongo ga _____', 'FILL_IN_BLANK', 'e4a28dc3-4952-11f1-a796-e00af6a25786'),
('db61bcab-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"見える (mieru) vs 見られる (mirareru): Which is about ability?\",\"options\":[\"見える only\",\"見られる only\",\"見える is ability, 来られる is possibility\",\"見える is ability, 見られる is possibility\"],\"correctIndex\":3,\"explanation\":\"見える is natural ability. 見られる is something being possible/allowed.\"}', 20, 'Can vs might: 見える vs 見られる', 'MULTIPLE_CHOICE', 'e4a28dc3-4952-11f1-a796-e00af6a25786'),
('db61bd6b-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"Kono hon wa _____. This book can be read easily. (read)\",\"answer\":\"読めます\",\"hints\":[\"can read\"],\"explanation\":\"読めます (yomemasu) is the polite potential form of 読む.\"}', 15, 'Fill in: Kono hon wa _____', 'FILL_IN_BLANK', 'e4a28dc3-4952-11f1-a796-e00af6a25786'),
('db634a2b-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"What does 便利 (benri) mean?\",\"options\":[\"Beautiful\",\"Convenient\",\"Expensive\",\"Dangerous\"],\"correctIndex\":1,\"explanation\":\"便利 (benri) means convenient or useful.\"}', 15, 'What does 便利 mean?', 'MULTIPLE_CHOICE', 'e4a28e1d-4952-11f1-a796-e00af6a25786'),
('db65da2c-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"What is the volitional form of 行く (iku - to go)?\",\"options\":[\"行こう\",\"行きよう\",\"行いる\",\"行けう\"],\"correctIndex\":0,\"explanation\":\"Volitional of 行く is 行こう (ikou), meaning Let us go.\"}', 20, 'Volitional of 行く?', 'MULTIPLE_CHOICE', 'e4a3604a-4952-11f1-a796-e00af6a25786'),
('db65e3e3-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"_____ tabemashou. Let us eat. (shall)\",\"answer\":\"食べましょう\",\"hints\":[\"volitional of 食べる\"],\"explanation\":\"食べましょう is the polite volitional form of 食べる.\"}', 15, 'Fill in: _____ tabemashou', 'FILL_IN_BLANK', 'e4a3604a-4952-11f1-a796-e00af6a25786'),
('db674fcd-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"What does 経験 (keiken) mean?\",\"options\":[\"Examination\",\"Experience\",\"Experiment\",\"Expression\"],\"correctIndex\":1,\"explanation\":\"経験 (keiken) means experience.\"}', 15, 'What does 経験 mean?', 'MULTIPLE_CHOICE', 'e4a36937-4952-11f1-a796-e00af6a25786'),
('db675acd-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"_____ means situation or circumstances. (joukyou)\",\"answer\":\"状況\",\"hints\":[\"state\"],\"explanation\":\"状況 (joukyou) means situation or circumstances.\"}', 15, 'Fill in: _____ means situation', 'FILL_IN_BLANK', 'e4a36937-4952-11f1-a796-e00af6a25786'),
('db6913c9-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"What is the passive form of 食べる (taberu)?\",\"options\":[\"食べらる\",\"食べられる\",\"食べさせる\",\"食べれる\"],\"correctIndex\":1,\"explanation\":\"られる is added: 食べられる (taberareru) means to be eaten.\"}', 20, 'Passive of 食べる?', 'MULTIPLE_CHOICE', 'e4a369f3-4952-11f1-a796-e00af6a25786'),
('db691c39-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"Kodomo ni hon wo _____. Make the child read the book. (read)\",\"answer\":\"読ませた\",\"hints\":[\"causative past\"],\"explanation\":\"読ませた is causative past: make someone do something.\"}', 20, 'Fill in: Kodomo ni hon wo _____', 'FILL_IN_BLANK', 'e4a369f3-4952-11f1-a796-e00af6a25786'),
('db691d78-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"食べられる\",\"right\":\"Be eaten (passive)\"},{\"left\":\"食べさせる\",\"right\":\"Make eat (causative)\"},{\"left\":\"読まれる\",\"right\":\"Be read (passive)\"},{\"left\":\"読ませる\",\"right\":\"Make read (causative)\"}]}', 30, 'Match passive and causative', 'MATCHING', 'e4a369f3-4952-11f1-a796-e00af6a25786'),
('db691e1e-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"What is the causative-passive of 行く (iku)?\",\"options\":[\"行かれる\",\"行かせる\",\"行かせられる\",\"行かれる\"],\"correctIndex\":2,\"explanation\":\"行かせられる: be made to go. Sometimes shortened to 行かされる.\"}', 20, 'Causative-passive of 行く?', 'MULTIPLE_CHOICE', 'e4a369f3-4952-11f1-a796-e00af6a25786'),
('db691eb1-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"友達に泣か_____. I was made to cry by my friend. (passive causative)\",\"answer\":\"れた\",\"hints\":[\"was made to\"],\"explanation\":\"泣かせれた = was made to cry (causative-passive).\"}', 20, 'Fill in: 友達に泣か_____', 'FILL_IN_BLANK', 'e4a369f3-4952-11f1-a796-e00af6a25786');
INSERT INTO `exercises` (`id`, `created_at`, `order_index`, `points`, `question_data`, `time_limit_seconds`, `title`, `type`, `lesson_id`) VALUES
('db6c16bd-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"In a Japanese reading passage, what is most important to identify first?\",\"options\":[\"New vocabulary\",\"Main idea/argument\",\"Grammar patterns\",\"Kanji readings\"],\"correctIndex\":1,\"explanation\":\"Identifying the main idea is the first step in reading comprehension.\"}', 20, 'Reading: Main idea?', 'MULTIPLE_CHOICE', 'e4a36aaf-4952-11f1-a796-e00af6a25786'),
('db6c204b-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 2, 10, '{\"question\":\"_____ (ketsuron) means conclusion or summary.\",\"answer\":\"結論\",\"hints\":[\"end\"],\"explanation\":\"結論 (ketsuron) means conclusion.\"}', 15, 'Fill in: _____ means conclusion', 'FILL_IN_BLANK', 'e4a36aaf-4952-11f1-a796-e00af6a25786'),
('db6c5e01-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 3, 15, '{\"pairs\":[{\"left\":\"最初\",\"right\":\"First\"},{\"left\":\"結論\",\"right\":\"Conclusion\"},{\"left\":\"しかし\",\"right\":\"However\"},{\"left\":\"例えば\",\"right\":\"For example\"}]}', 30, 'Match reading strategies', 'MATCHING', 'e4a36aaf-4952-11f1-a796-e00af6a25786'),
('db6c5ed0-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 4, 10, '{\"question\":\"しかし at the beginning of a sentence means:\",\"options\":[\"Also\",\"However\",\"Therefore\",\"For example\"],\"correctIndex\":1,\"explanation\":\"しかし means however, indicating a contrast.\"}', 15, 'What does しかし mean?', 'MULTIPLE_CHOICE', 'e4a36aaf-4952-11f1-a796-e00af6a25786'),
('db6c5f49-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 5, 10, '{\"question\":\"_____ means for example (tatoeba).\",\"answer\":\"例えば\",\"hints\":[\"example\"],\"explanation\":\"例えば (tatoeba) means for example.\"}', 15, 'Fill in: _____ means for example', 'FILL_IN_BLANK', 'e4a36aaf-4952-11f1-a796-e00af6a25786'),
('db6dbbc5-4965-11f1-a796-e00af6a25786', '2026-05-06 23:08:44.000000', 1, 10, '{\"question\":\"Which is a casual greeting in Japanese?\",\"options\":[\"おはようございます\",\"やあ\",\"いただきます\",\"失礼します\"],\"correctIndex\":1,\"explanation\":\"やあ (yaa) is a casual greeting. おはようございます is formal.\"}', 15, 'Casual vs formal greeting?', 'MULTIPLE_CHOICE', 'e4a4307c-4952-11f1-a796-e00af6a25786'),
