('e4efaf1f-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Wake up\",\"right\":\"6 AM\"},{\"left\":\"Have breakfast\",\"right\":\"7 AM\"},{\"left\":\"Go to work\",\"right\":\"8 AM\"},{\"left\":\"Sleep\",\"right\":\"10 PM\"}]}', 30, 'Match routine to time', 'MATCHING', 'e49d3d86-4952-11f1-a796-e00af6a25786'),
