('e4f1714c-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"Can I pay by _____? (credit card method)\",\"answer\":\"credit card\",\"hints\":[\"card payment\"],\"explanation\":\"Credit card is a common payment method.\"}', 15, 'Complete: Can I pay by _____?', 'FILL_IN_BLANK', 'e49d475d-4952-11f1-a796-e00af6a25786'),
