('e4f17280-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"A shirt is on sale. What does this mean?\",\"options\":[\"More expensive than usual\",\"Cheaper than usual\",\"Same price\",\"Sold out\"],\"correctIndex\":1,\"explanation\":\"On sale means the price is reduced, making it cheaper.\"}', 15, 'What does \"on sale\" mean?', 'MULTIPLE_CHOICE', 'e49d475d-4952-11f1-a796-e00af6a25786'),
('e4f17301-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"This jacket is too _____. I will not buy it. (expensive)\",\"answer\":\"expensive\",\"hints\":[\"opposite of cheap\"],\"explanation\":\"Too expensive means the price is too high for you to buy.\"}', 15, 'Fill in: This jacket is too _____. I will not buy it', 'FILL_IN_BLANK', 'e49d475d-4952-11f1-a796-e00af6a25786'),
('e4f23d26-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 10, '{\"question\":\"She _____ (read) a book right now.\",\"options\":[\"read\",\"reads\",\"is reading\",\"are reading\"],\"correctIndex\":2,\"explanation\":\"Present continuous: am/is/are + verb-ing. She is reading.\"}', 20, 'Choose the correct form', 'MULTIPLE_CHOICE', 'e49d47ed-4952-11f1-a796-e00af6a25786'),
('e4f24076-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"Look! The children _____ (play) in the park.\",\"answer\":\"are playing\",\"hints\":[\"action happening now\"],\"explanation\":\"Look! signals present continuous: are + playing.\"}', 20, 'Fill in: Look! The children _____', 'FILL_IN_BLANK', 'e49d47ed-4952-11f1-a796-e00af6a25786'),
('e4f2411c-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 10, '{\"question\":\"Which sentence uses present continuous?\",\"options\":[\"I eat breakfast\",\"I am eating breakfast\",\"I ate breakfast\",\"I eat breakfast every day\"],\"correctIndex\":1,\"explanation\":\"I am eating breakfast uses am + verb-ing, showing an action happening now.\"}', 15, 'Which sentence is present continuous?', 'MULTIPLE_CHOICE', 'e49d47ed-4952-11f1-a796-e00af6a25786'),
('e4f241a1-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"He is work ing hard. (fix the sentence)\",\"answer\":\"He is working hard.\",\"hints\":[\"remove the space\"],\"explanation\":\"Working is one word: is + working (not work ing).\"}', 20, 'Correct the error', 'FILL_IN_BLANK', 'e49d47ed-4952-11f1-a796-e00af6a25786'),
('e4f2421d-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 15, '{\"pairs\":[{\"left\":\"Right now\",\"right\":\"Present continuous\"},{\"left\":\"Every day\",\"right\":\"Present simple\"},{\"left\":\"Look!\",\"right\":\"Present continuous\"},{\"left\":\"Usually\",\"right\":\"Present simple\"}]}', 30, 'Match with present continuous', 'MATCHING', 'e49d47ed-4952-11f1-a796-e00af6a25786'),
('e4f325b1-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 10, '{\"question\":\"In most countries, which season has snow?\",\"options\":[\"Spring\",\"Summer\",\"Autumn\",\"Winter\"],\"correctIndex\":3,\"explanation\":\"Winter is typically the cold season when it snows in many countries.\"}', 15, 'What season has snow?', 'MULTIPLE_CHOICE', 'e49d4861-4952-11f1-a796-e00af6a25786'),
('e4f32843-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"It is very _____ today. Take an umbrella. (rain)\",\"answer\":\"rainy\",\"hints\":[\"rain + y\"],\"explanation\":\"Rainy describes weather with rain.\"}', 15, 'Fill in: It is very _____ today', 'FILL_IN_BLANK', 'e49d4861-4952-11f1-a796-e00af6a25786'),
('e4f328b9-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Hot and sunny\",\"right\":\"Summer\"},{\"left\":\"Cold and snowy\",\"right\":\"Winter\"},{\"left\":\"Cool and colorful leaves\",\"right\":\"Autumn\"},{\"left\":\"Warm and flowers blooming\",\"right\":\"Spring\"}]}', 30, 'Match weather to seasons', 'MATCHING', 'e49d4861-4952-11f1-a796-e00af6a25786'),
('e4f37aad-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"What is a synonym for hot weather?\",\"options\":[\"Cold\",\"Warm\",\"Cool\",\"Freezing\"],\"correctIndex\":1,\"explanation\":\"Warm is similar to hot but less extreme.\"}', 15, 'What is a synonym for \"hot\"?', 'MULTIPLE_CHOICE', 'e49d4861-4952-11f1-a796-e00af6a25786'),
('e4f37b9d-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"The sun is _____ today. It is very bright. (shine)\",\"answer\":\"shining\",\"hints\":[\"shine + ing\"],\"explanation\":\"The sun is shining means the sun is giving out light.\"}', 15, 'Complete: The sun is _____ today', 'FILL_IN_BLANK', 'e49d4861-4952-11f1-a796-e00af6a25786'),
('e4f43fb9-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 15, '{\"question\":\"The customer ordered: A table for 2 and a glass of red wine. What did the customer order?\",\"options\":[\"Coffee and cake\",\"Tea and sandwich\",\"Water only\",\"A table for 2 and red wine\"],\"correctIndex\":3,\"explanation\":\"The customer ordered a table for 2 and a glass of red wine.\"}', 45, 'Listen and choose the correct answer', 'LISTENING_CHOICE', 'e49e1f6d-4952-11f1-a796-e00af6a25786'),
