('e4f442ef-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"A restaurant adds a service charge. What is this?\",\"options\":[\"Tip for the waiter\",\"Extra food\",\"Music fee\",\"Table rental\"],\"correctIndex\":0,\"explanation\":\"Service charge is an additional fee, usually a tip for the service staff.\"}', 20, 'What does \"service charge\" mean?', 'MULTIPLE_CHOICE', 'e49e1f6d-4952-11f1-a796-e00af6a25786'),
('e4f44349-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"Could I have the _____, please? I want to pay. (bill)\",\"answer\":\"bill\",\"hints\":[\"payment\"],\"explanation\":\"The bill is the receipt with the total amount to pay.\"}', 15, 'Complete: Could I have the _____?', 'FILL_IN_BLANK', 'e49e1f6d-4952-11f1-a796-e00af6a25786'),
('e4f512a4-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 10, '{\"question\":\"She _____ (watch) TV when the phone rang.\",\"options\":[\"watched\",\"was watching\",\"is watching\",\"watches\"],\"correctIndex\":1,\"explanation\":\"Past continuous (was watching) for the ongoing action, past simple (rang) for the interruption.\"}', 25, 'Choose past simple or past continuous', 'MULTIPLE_CHOICE', 'e49e2181-4952-11f1-a796-e00af6a25786'),
('e4f5155d-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"Yesterday, I _____ (go) to school by bus.\",\"answer\":\"went\",\"hints\":[\"past of go\"],\"explanation\":\"Went is the past simple of go.\"}', 15, 'Fill in: Yesterday, I _____ to school', 'FILL_IN_BLANK', 'e49e2181-4952-11f1-a796-e00af6a25786'),
('e4f51600-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 10, '{\"question\":\"He goed to the market yesterday. Which is correct?\",\"options\":[\"He goed to the market\",\"He went to the market\",\"He goed at the market\",\"He going to market\"],\"correctIndex\":1,\"explanation\":\"Went is the correct past simple of go.\"}', 15, 'Correct the error', 'MULTIPLE_CHOICE', 'e49e2181-4952-11f1-a796-e00af6a25786'),
('e4f51689-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 15, '{\"pairs\":[{\"left\":\"go\",\"right\":\"went\"},{\"left\":\"see\",\"right\":\"saw\"},{\"left\":\"eat\",\"right\":\"ate\"},{\"left\":\"take\",\"right\":\"took\"}]}', 30, 'Match verbs to past forms', 'MATCHING', 'e49e2181-4952-11f1-a796-e00af6a25786'),
('e4f51709-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"While I _____ (wait) for the bus, it rained heavily.\",\"answer\":\"was waiting\",\"hints\":[\"past continuous with while\"],\"explanation\":\"While + past continuous shows an ongoing action interrupted by another event.\"}', 20, 'Fill in: While I _____ (wait), it rained', 'FILL_IN_BLANK', 'e49e2181-4952-11f1-a796-e00af6a25786');
INSERT INTO `exercises` (`id`, `created_at`, `order_index`, `points`, `question_data`, `time_limit_seconds`, `title`, `type`, `lesson_id`) VALUES
('e4f5efb4-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 10, '{\"question\":\"I _____ (go) to Paris next week. It is already planned.\",\"options\":[\"will go\",\"am going\",\"go\",\"went\"],\"correctIndex\":1,\"explanation\":\"Present continuous (am going) is used for definite future plans.\"}', 20, 'Choose correct future form', 'MULTIPLE_CHOICE', 'e49e2200-4952-11f1-a796-e00af6a25786'),
('e4f5f269-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"I think it _____ rain tomorrow. I am not sure.\",\"answer\":\"will\",\"hints\":[\"prediction\"],\"explanation\":\"Will is used for predictions about the future, especially when not certain.\"}', 15, 'Fill in: I think it _____ rain tomorrow', 'FILL_IN_BLANK', 'e49e2200-4952-11f1-a796-e00af6a25786'),
('e4f5f319-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"I am meeting Sarah\",\"right\":\"Planned arrangement\"},{\"left\":\"I will call you\",\"right\":\"Instant decision\"},{\"left\":\"I am going to travel\",\"right\":\"Intention\"},{\"left\":\"It might snow\",\"right\":\"Possibility\"}]}', 30, 'Match future expressions', 'MATCHING', 'e49e2200-4952-11f1-a796-e00af6a25786'),
('e4f5f3a3-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"When do we use going to for plans and will for predictions?\",\"options\":[\"Going to for plans, will for predictions\",\"Will for plans, going to for predictions\",\"They are exactly the same\",\"Neither is correct\"],\"correctIndex\":0,\"explanation\":\"Going to is for planned intentions. Will is for spontaneous decisions and predictions.\"}', 20, 'What is the difference: will vs going to?', 'MULTIPLE_CHOICE', 'e49e2200-4952-11f1-a796-e00af6a25786'),
('e4f5f448-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"We are _____ to visit our grandmother next Sunday. It is a plan.\",\"answer\":\"going\",\"hints\":[\"going to\"],\"explanation\":\"Are going to shows a planned arrangement for the future.\"}', 15, 'Fill in: We are _____ to visit our grandmother', 'FILL_IN_BLANK', 'e49e2200-4952-11f1-a796-e00af6a25786'),
('e4f6d726-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 10, '{\"question\":\"I am facing north. I turn left. Which direction am I now facing?\",\"options\":[\"North\",\"South\",\"East\",\"West\"],\"correctIndex\":2,\"explanation\":\"Facing north, turning left means you now face west.\"}', 15, 'Turn left or right?', 'MULTIPLE_CHOICE', 'e49e2258-4952-11f1-a796-e00af6a25786'),
('e4f6da71-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"Go _____ the traffic light and turn right. (straight past)\",\"answer\":\"past\",\"hints\":[\"continue past\"],\"explanation\":\"Go past the traffic light means continue straight past it.\"}', 15, 'Fill in: Go _____ the traffic light', 'FILL_IN_BLANK', 'e49e2258-4952-11f1-a796-e00af6a25786'),
('e4f71a95-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Turn left\",\"right\":\"90 degrees to the west\"},{\"left\":\"Go straight\",\"right\":\"Continue forward\"},{\"left\":\"Turn right\",\"right\":\"90 degrees to the east\"},{\"left\":\"At the corner\",\"right\":\"On the bend\"}]}', 30, 'Match directions', 'MATCHING', 'e49e2258-4952-11f1-a796-e00af6a25786'),
('e4f71bf1-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"What direction is opposite to north?\",\"options\":[\"East\",\"West\",\"South\",\"Northeast\"],\"correctIndex\":2,\"explanation\":\"South is opposite to north on a compass.\"}', 10, 'What is opposite of north?', 'MULTIPLE_CHOICE', 'e49e2258-4952-11f1-a796-e00af6a25786'),
('e4f71c68-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"The bank is _____ the supermarket. Next to means beside.\",\"answer\":\"next to\",\"hints\":[\"beside\"],\"explanation\":\"Next to means beside or adjacent to.\"}', 15, 'Fill in: The bank is _____ the supermarket', 'FILL_IN_BLANK', 'e49e2258-4952-11f1-a796-e00af6a25786'),
('e4f7f97a-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 1, 10, '{\"question\":\"Which of these is typically considered a hobby?\",\"options\":[\"Going to work\",\"Cooking\",\"Sleeping\",\"Attending meetings\"],\"correctIndex\":1,\"explanation\":\"Cooking is a leisure activity and a common hobby.\"}', 15, 'Which is a hobby?', 'MULTIPLE_CHOICE', 'e49e22a7-4952-11f1-a796-e00af6a25786'),
('e4f802b8-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 2, 10, '{\"question\":\"She enjoys _____ photos in her free time. (take)\",\"answer\":\"taking\",\"hints\":[\"enjoy + verb-ing\"],\"explanation\":\"Enjoy is followed by a gerund (verb-ing). Taking photos.\"}', 15, 'Fill in: She enjoys _____ photos', 'FILL_IN_BLANK', 'e49e22a7-4952-11f1-a796-e00af6a25786'),
('e4f8038f-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Reading\",\"right\":\"Knowledge\"},{\"left\":\"Swimming\",\"right\":\"Physical fitness\"},{\"left\":\"Playing guitar\",\"right\":\"Musical skill\"},{\"left\":\"Painting\",\"right\":\"Creative expression\"}]}', 30, 'Match hobbies to benefits', 'MATCHING', 'e49e22a7-4952-11f1-a796-e00af6a25786'),
('e4f80417-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 4, 10, '{\"question\":\"I read books in my spare time. What does spare time mean?\",\"options\":[\"Working hours\",\"Free time\",\"Study time\",\"Sleeping time\"],\"correctIndex\":1,\"explanation\":\"Spare time or free time means time not used for work or obligations.\"}', 15, 'What does \"in my spare time\" mean?', 'MULTIPLE_CHOICE', 'e49e22a7-4952-11f1-a796-e00af6a25786'),
('e4f8048c-4952-11f1-a796-e00af6a25786', '2026-05-06 20:53:00.000000', 5, 10, '{\"question\":\"His hobby is _____ stamps. It is called philately. (collect)\",\"answer\":\"collecting\",\"hints\":[\"verb-ing after is\"],\"explanation\":\"A hobby can be expressed as verb-ing: collecting stamps.\"}', 15, 'Fill in: His hobby is _____ stamps', 'FILL_IN_BLANK', 'e49e22a7-4952-11f1-a796-e00af6a25786'),
