('f0826803-6efe-47db-b406-41ab59e84947', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"\\\"Pode limpar o quarto?\\\" trong tiếng Bồ Đào Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Co the don phong khong?\",\"hints\":[\"cleaning\"],\"explanation\":\"Pode = Có thể. limpar = Dọn. o quarto = Phòng.\"}', 15, 'Điền: Pode limpar o quarto? = _____', 'FILL_IN_BLANK', 'e4e7de8f-4952-11f1-a796-e00af6a25786'),
('f084c8cf-4005-4ace-a89f-cacdb0fe501f', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"\\\"¿Cuánto cuesta?\\\" trong tiếng Tây Ban Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Bao nhieu tien?\",\"hints\":[\"price\"],\"explanation\":\"¿Cuánto cuesta? = Bao nhiêu tiền? (hỏi giá).\"}', 20, 'Điền: ¿Cuánto cuesta? = _____', 'FILL_IN_BLANK', 'e4d0fc72-4952-11f1-a796-e00af6a25786'),
('f0c3d48d-3691-407f-84b0-7f038ed39eaf', '2026-05-07 20:00:00.000000', 5, 10, '{\"question\":\"\\\"Duvido que\\\" trong tiếng Bồ Đào Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Toi nghi khong\",\"hints\":[\"doubt\"],\"explanation\":\"Duvido que = Tôi nghi là không (nghi ngo, đòi hỏi conjunctivo).\"}', 15, 'Điền: Duvido que = _____', 'FILL_IN_BLANK', 'e4e64856-4952-11f1-a796-e00af6a25786'),
('f16ddbd1-3a71-4587-bf8f-bc55486e1146', '2026-05-07 19:40:00.000000', 1, 10, '{\"question\":\"妈妈 (māma) in Mandarin means _____ in English.\",\"options\":[\"Father\",\"Mother\",\"Sister\",\"Brother\"],\"correctIndex\":1,\"explanation\":\"妈妈 = Mother. 爸爸 = Father.\"}', 20, '妈妈 means what?', 'MULTIPLE_CHOICE', 'e4ab7614-4952-11f1-a796-e00af6a25786'),
('f1d502a3-bb65-43d4-9637-5d08c1930714', '2026-05-07 19:00:00.000000', 5, 10, '{\"question\":\"Sau in Vietnamese means _____ in English.\",\"answer\":\"Six\",\"hints\":[\"number\"],\"explanation\":\"Sau = 6. Bay = 7, Tam = 8, Chin = 9.\"}', 15, 'Fill in: _____ = Six', 'FILL_IN_BLANK', 'e4d767d9-4952-11f1-a796-e00af6a25786'),
('f2001a01-0001-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"Je _____ (acheter) une maison si je gagnais a la loterie. Chon dap an dung.\",\r\n  \"options\":[\"acheterais\",\"achetais\",\"ai achete\",\"acheterai\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"acheterais = mua (conditionnel present). Cau truc: Si + imparfait + conditionnel present.\"}', 20, 'Dien: Je _____ une maison si je gagnais a la loterie', 'MULTIPLE_CHOICE', 'e4c85d78-4952-11f1-a796-e00af6a25786'),
('f2001a02-0002-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"Si j avais le temps, je _____ (apprendre) l italien. Dien dap an dung.\",\r\n  \"answer\":\"apprendrais\",\r\n  \"hints\":[\"conditionnel present\"],\r\n  \"explanation\":\"apprendrais = se hoc (conditionnel present cua apprendre). Dieu kien: Si + imparfait + conditionnel present.\"}', 15, 'Dien: Si j avais le temps, je _____ l italien', 'FILL_IN_BLANK', 'e4c85d78-4952-11f1-a796-e00af6a25786'),
('f2001a03-0003-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[\r\n   {\"left\":\"Je parlerais\",\"right\":\"Toi se noi\"},\r\n   {\"left\":\"Nous irions\",\"right\":\"Chung toi se di\"},\r\n   {\"left\":\"Elle serait\",\"right\":\"Co ay se la\"},\r\n   {\"left\":\"Vous feriez\",\"right\":\"Ban se lam\"}\r\n ],\r\n \"explanation\":\"Cac dong tu trong conditionnel present.\"}', 30, 'Noi dong tu Conditionnel Present voi nghia', 'MATCHING', 'e4c85d78-4952-11f1-a796-e00af6a25786'),
('f2001a04-0004-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"Je _____ (pouvoir) vous aider si vous vouliez. Chon dap an dung.\",\r\n  \"options\":[\"pourrais\",\"pouvais\",\"ai pu\",\"pourrai\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"pourrais = co the (conditionnel present cua pouvoir). VD: Je pourrais vous aider = Toi co the giup ban.\"}', 15, 'Dien: Je _____ vous aider si vous vouliez', 'MULTIPLE_CHOICE', 'e4c85d78-4952-11f1-a796-e00af6a25786'),
('f2001a05-0005-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 5, 10, '{\"question\":\"Je voudrais une tasse de cafe. Câu nay nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Toi muon mot ly cafe\",\r\n  \"hints\":[\"politesse\"],\r\n  \"explanation\":\"Je voudrais = Toi muon / Toi se muon. Day la cach noi lich su rat pho bien trong tieng Phap.\"}', 15, 'Dien: Je voudrais = _____', 'FILL_IN_BLANK', 'e4c85d78-4952-11f1-a796-e00af6a25786'),
('f2001a06-0006-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"Elle a dit: Je viendrai demain. -> Elle a dit qu elle _____.\",\r\n  \"options\":[\"viendrait\",\"viendra\",\"est venue\",\"vienne\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"viendrait = se den (discours rapporte: dien bien truc tiep + imparfait). Lenh chinh: said that + imparfait.\"}', 20, 'Chuyen: Elle a dit qu elle _____', 'MULTIPLE_CHOICE', 'e4c862a6-4952-11f1-a796-e00af6a25786'),
('f2001a07-0007-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"Il a dit: Je suis content. -> Il a dit qu il _____ content.\",\r\n  \"answer\":\"etait\",\r\n  \"hints\":[\"discours rapporte\"],\r\n  \"explanation\":\"etait = vui (imparfait trong discours rapporte). Tu suis (present) chuyen thanh etait (imparfait).\"}', 15, 'Dien: Il a dit qu il _____ content', 'FILL_IN_BLANK', 'e4c862a6-4952-11f1-a796-e00af6a25786'),
('f2001a08-0008-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[\r\n   {\"left\":\"Il a dit que\",\"right\":\"Anh ay noi rang\"},\r\n   {\"left\":\"Elle a affirme que\",\"right\":\"Co ay khang dinh rang\"},\r\n   {\"left\":\"Il a ajoute que\",\"right\":\"Anh ay them rang\"},\r\n   {\"left\":\"Elle a explique que\",\"right\":\"Co ay giai thich rang\"}\r\n ],\r\n \"explanation\":\"Cac dong tu chi dao trong discours rapporte.\"}', 30, 'Noi dong tu discours rapporte voi nghia', 'MATCHING', 'e4c862a6-4952-11f1-a796-e00af6a25786');
INSERT INTO `exercises` (`id`, `created_at`, `order_index`, `points`, `question_data`, `time_limit_seconds`, `title`, `type`, `lesson_id`) VALUES
('f2001a09-0009-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"Nous _____ (venir) si le temps le permettait. Dieu kien.\",\r\n  \"answer\":\"viendrions\",\r\n  \"hints\":[\"conditionnel present\"],\r\n  \"explanation\":\"viendrions = se den (conditionnel present cua venir). Dieu kien hau: Si + imparfait + conditionnel present.\"}', 15, 'Dien: Nous _____ si le temps le permettait', 'FILL_IN_BLANK', 'e4c862a6-4952-11f1-a796-e00af6a25786'),
('f2001a10-0010-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 5, 10, '{\"question\":\"Hier, je suis alle au cinema. -> Dans le discours reporte, hier devient _____.\",\r\n  \"answer\":\"la veille\",\r\n  \"hints\":[\"decalage temporel\"],\r\n  \"explanation\":\"Trong discours reporte, chỉ thời gian thay đổi: hier -> la veille (ngay truoc do), demain -> le lendemain.\"}', 15, 'Dien: hier -> _____ (discours reporte)', 'FILL_IN_BLANK', 'e4c862a6-4952-11f1-a796-e00af6a25786'),
('f2001a11-0011-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"Premiere etape trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Buoc dau tien\",\r\n  \"hints\":[\"etapes\"],\r\n  \"explanation\":\"Premiere etape = Buoc/Thao tac dau tien. Dung de bieu thi cac buoc trong bai viet.\"}', 20, 'Dien: Premiere etape = _____', 'FILL_IN_BLANK', 'e4c86350-4952-11f1-a796-e00af6a25786'),
('f2001a12-0012-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"De plus trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Hon nua\",\r\n  \"hints\":[\"connector\"],\r\n  \"explanation\":\"De plus = Hon nua / Them vao do. Day la noi tu ket noi bai viet.\"}', 15, 'Dien: De plus = _____', 'FILL_IN_BLANK', 'e4c86350-4952-11f1-a796-e00af6a25786'),
('f2001a13-0013-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[\r\n   {\"left\":\"Premiere etape\",\"right\":\"Buoc dau tien\"},\r\n   {\"left\":\"En conclusion\",\"right\":\"Ket luan\"},\r\n   {\"left\":\"De plus\",\"right\":\"Hon nua\"},\r\n   {\"left\":\"Par ailleurs\",\"right\":\"Mat khac\"}\r\n ],\r\n \"explanation\":\"Cac tu vung bai viet hoc thuat trong tieng Phap.\"}', 30, 'Noi tu vung bai viet hoc thuat', 'MATCHING', 'e4c86350-4952-11f1-a796-e00af6a25786'),
('f2001a14-0014-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"En conclusion trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Ket luan\",\r\n  \"hints\":[\"conclusion\"],\r\n  \"explanation\":\"En conclusion = Ket luan / Tom lai. Dung o cuoi bai viet.\"}', 15, 'Dien: En conclusion = _____', 'FILL_IN_BLANK', 'e4c86350-4952-11f1-a796-e00af6a25786'),
('f2001a15-0015-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 5, 10, '{\"question\":\"D une part... d autre part trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Mot phia... phia con lai\",\r\n  \"hints\":[\"contrast\"],\r\n  \"explanation\":\"D une part... d autre part = Mot phia... phia con lai. Dung de bieu thi hai mat cua van de.\"}', 15, 'Dien: D une part... d autre part = _____', 'FILL_IN_BLANK', 'e4c86350-4952-11f1-a796-e00af6a25786'),
('f2001a16-0016-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"A voir le cafard trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Cam thay chan nan\",\r\n  \"hints\":[\"idiom\"],\r\n  \"explanation\":\"A voir le cafard = Cam thay chan nan / Buc tinh. Bat cua trai (cafard) la bieu tuong cua su cham chan.\"}', 20, 'Dien: A voir le cafard = _____', 'FILL_IN_BLANK', 'e4c863ba-4952-11f1-a796-e00af6a25786'),
('f2001a17-0017-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"Thanh ngu nao nghia la rat dat trong tieng Phap?\",\r\n  \"options\":[\"Coouter un bras\",\"Coouter les yeux de la tete\",\"Coouter une fortune\",\"Coouter cher\"],\r\n  \"correctIndex\":1,\r\n  \"explanation\":\"Coouter les yeux de la tete = Dat that mat (rat dat). Coouter un bras = Mat that (rat dat).\"}', 15, 'Rat dat trong tieng Phap la thanh ngu nao?', 'MULTIPLE_CHOICE', 'e4c863ba-4952-11f1-a796-e00af6a25786'),
('f2001a18-0018-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[\r\n   {\"left\":\"A voir le cafard\",\"right\":\"Cam thay chan nan\"},\r\n   {\"left\":\"Poser un lapin\",\"right\":\"Huy ke hoach\"},\r\n   {\"left\":\"Coouter les yeux de la tete\",\"right\":\"Dat that mat\"},\r\n   {\"left\":\"Tomber dans les pommes\",\"right\":\"Ngat xiu\"}\r\n ],\r\n \"explanation\":\"Cac thanh ngu pho bien trong tieng Phap.\"}', 30, 'Noi thanh ngu Phap voi nghia', 'MATCHING', 'e4c863ba-4952-11f1-a796-e00af6a25786'),
('f2001a19-0019-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"Faire la grise mine trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"To la mat khong vui\",\r\n  \"hints\":[\"expression\"],\r\n  \"explanation\":\"Faire la grise mine = To la mat khong vui / Gia mat cau. Gris(e) mine = mat xam.\"}', 15, 'Dien: Faire la grise mine = _____', 'FILL_IN_BLANK', 'e4c863ba-4952-11f1-a796-e00af6a25786'),
('f2001a20-0020-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 5, 10, '{\"question\":\"Mettre son grain de sel trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Chen vao y kien cua nguoi khac\",\r\n  \"hints\":[\"idiom\"],\r\n  \"explanation\":\"Mettre son grain de sel = Chen vao / Xen nghia (that lit: bo mot hat muoi vao). Day la thanh ngu pho bien.\"}', 15, 'Dien: Mettre son grain de sel = _____', 'FILL_IN_BLANK', 'e4c863ba-4952-11f1-a796-e00af6a25786'),
('f2001a21-0021-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 1, 10, '{\"question\":\"A mon avis trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Theo y kien cua toi\",\r\n  \"hints\":[\"opinion\"],\r\n  \"explanation\":\"A mon avis = Theo y kien cua toi / Toi nghi rang. Day la cach bieu dat y kien rat pho bien.\"}', 20, 'Dien: A mon avis = _____', 'FILL_IN_BLANK', 'e4c86428-4952-11f1-a796-e00af6a25786'),
('f2001a22-0022-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"Cau nao nghia la Toi phan doi trong tieng Phap?\",\r\n  \"options\":[\"Je suis d accord\",\"Je ne suis pas d accord\",\"C est evident\",\"Je partage ton avis\"],\r\n  \"correctIndex\":1,\r\n  \"explanation\":\"Je ne suis pas d accord = Toi phan doi. Etre d accord = dong y.\"}', 15, 'Toi phan doi trong tieng Phap?', 'MULTIPLE_CHOICE', 'e4c86428-4952-11f1-a796-e00af6a25786'),
('f2001a23-0023-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[\r\n   {\"left\":\"A mon avis\",\"right\":\"Theo y kien toi\"},\r\n   {\"left\":\"En revanche\",\"right\":\"Nguoc lai\"},\r\n   {\"left\":\"D une part... d autre part\",\"right\":\"Mot phia... phia con lai\"},\r\n   {\"left\":\"En effet\",\"right\":\"Thuc ra / That ra\"}\r\n ],\r\n \"explanation\":\"Cac tu vung tranh luan trong tieng Phap.\"}', 30, 'Noi tu vung tranh luan Phap', 'MATCHING', 'e4c86428-4952-11f1-a796-e00af6a25786'),
('f2001a24-0024-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"En conclusion trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"Ket luan\",\r\n  \"hints\":[\"conclusion\"],\r\n  \"explanation\":\"En conclusion = Ket luan / Tom lai. Dung o cuoi bai tranh luan de tong ket quan diem.\"}', 15, 'Dien: En conclusion = _____', 'FILL_IN_BLANK', 'e4c86428-4952-11f1-a796-e00af6a25786'),
('f2001a25-0025-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 5, 10, '{\"question\":\"Pour reprendre trong tieng Phap nghia la _____ bang tieng Viet.\",\r\n  \"answer\":\"De lay lai\",\r\n  \"hints\":[\"argumentation\"],\r\n  \"explanation\":\"Pour reprendre = De lay lai / De quay lai chu de. Dung de quay lai mot van de trong tranh luan.\"}', 15, 'Dien: Pour reprendre = _____', 'FILL_IN_BLANK', 'e4c86428-4952-11f1-a796-e00af6a25786'),
('f2002b01-0001-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 6, 15, '{\"audioUrl\":\"https://audio.example.com/phone.mp3\",\r\n  \"question\":\"You hear: Good morning, this is Sarah from HR. Is Mr. Johnson available? What is Sarah calling about?\",\r\n  \"options\":[\"Sales inquiry\",\"HR matter\",\"Technical support\",\"Personal call\"],\r\n  \"correctIndex\":1,\r\n  \"explanation\":\"Sarah from HR is calling to speak with Mr. Johnson about an HR matter.\"}', 60, 'Listen: Business phone call', 'LISTENING_CHOICE', 'e49efd2a-4952-11f1-a796-e00af6a25786'),
('f2002b02-0002-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 7, 15, '{\"audioUrl\":\"https://audio.example.com/phone.mp3\",\r\n  \"question\":\"You hear: Could you hold for a moment please? I will transfer you to his extension. What does the speaker ask?\",\r\n  \"options\":[\"To wait on hold\",\"To call back later\",\"To speak slower\",\"To leave a message\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"The speaker asks the caller to hold while they transfer the call.\"}', 60, 'Listen: Transfer call', 'LISTENING_CHOICE', 'e49efd2a-4952-11f1-a796-e00af6a25786'),
('f2002b03-0003-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 6, 15, '{\"audioUrl\":\"https://audio.example.com/ielts_listening.mp3\",\r\n  \"question\":\"You hear: The lecture will begin in Section 3 on page 45. What is the speaker referring to?\",\r\n  \"options\":[\"A book\",\"A map\",\"A test paper\",\"A newspaper\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"The speaker refers to a book (lecture materials).\"}', 60, 'Listen: IELTS lecture excerpt', 'LISTENING_CHOICE', 'e49fe94f-4952-11f1-a796-e00af6a25786'),
('f2002b04-0004-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 7, 15, '{\"audioUrl\":\"https://audio.example.com/ielts_listening.mp3\",\r\n  \"question\":\"You hear: Remember to check your spelling before moving on. What advice does the speaker give?\",\r\n  \"options\":[\"Review vocabulary\",\"Check spelling\",\"Read aloud\",\"Skip difficult questions\"],\r\n  \"correctIndex\":1,\r\n  \"explanation\":\"The speaker advises students to check their spelling before continuing.\"}', 60, 'Listen: IELTS test tip', 'LISTENING_CHOICE', 'e49fe94f-4952-11f1-a796-e00af6a25786'),
('f2002b05-0005-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 6, 15, '{\"question\":\"留守番電話にメッセージを残してください。Nghia la _____ bang tieng Anh.\",\r\n  \"options\":[\"Please leave a message on the answering machine\",\"Please call back later\",\"The line is busy\",\"Hold the line please\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"留守番電話 = answering machine. メッセージを残してください = please leave a message.\"}', 20, 'Nghe: Dien thoai kinh doanh Nhat', 'LISTENING_CHOICE', 'e4a4f2cf-4952-11f1-a796-e00af6a25786'),
('f2002b06-0006-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 7, 15, '{\"question\":\"申し訳ありませんが、もう一度おっしゃっていただけますか。Nghia la _____ bang tieng Anh.\",\r\n  \"options\":[\"Could you please repeat that?\",\"Could you speak slower?\",\"Please hold\",\"Can you transfer me?\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"もう一度 = one more time. おっしゃっていただけますか = could you say (polite). Day la cach noi lich su trong kinh doanh.\"}', 20, 'Nghe: Noi chuyen dien thoai Nhat', 'LISTENING_CHOICE', 'e4a4f2cf-4952-11f1-a796-e00af6a25786'),
('f2002b07-0007-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 6, 15, '{\"audioUrl\":\"https://audio.example.com/topik_listening.mp3\",\r\n  \"question\":\"You hear: 오늘 날씨가 좋아서 공원에서 산책했습니다. What did the speaker do?\",\r\n  \"options\":[\"Studied at the library\",\"Walked in the park\",\"Went shopping\",\"Stayed home\"],\r\n  \"correctIndex\":1,\r\n  \"explanation\":\"오늘 = today. 날씨가 좋아서 = because the weather was good. 공원에서 산책했습니다 = walked in the park.\"}', 60, 'Nghe: TOPIK Listening Part 1', 'LISTENING_CHOICE', 'e4a92531-4952-11f1-a796-e00af6a25786'),
('f2002b08-0008-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 7, 15, '{\"audioUrl\":\"https://audio.example.com/topik_listening.mp3\",\r\n  \"question\":\"You hear: 저는 한국어학과 학생입니다. What is the speaker?\",\r\n  \"options\":[\"Korean language student\",\"English teacher\",\"University professor\",\"Office worker\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"저는 = I (topic marker). 한국어학과 = Korean language department. 학생입니다 = am a student.\"}', 60, 'Nghe: TOPIK Listening Part 2', 'LISTENING_CHOICE', 'e4a92531-4952-11f1-a796-e00af6a25786'),
('f2002b09-0009-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 6, 15, '{\"question\":\"Könnten Sie das bitte nochmal wiederholen? Nghia la _____ bang tieng Anh.\",\r\n  \"options\":[\"Could you please repeat that?\",\"Could you speak slower?\",\"Please hold the line\",\"Can I speak to your manager?\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"Könnten Sie = could you. bitte = please. nochmal = again. wiederholen = repeat.\"}', 20, 'Nghe: Dien thoai tieng Duc', 'LISTENING_CHOICE', 'e4ce9927-4952-11f1-a796-e00af6a25786'),
('f2002b10-0010-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 7, 15, '{\"question\":\"Ich verbinde Sie mit der Abteilungsleiterin. Nghia la _____ bang tieng Anh.\",\r\n  \"options\":[\"I am connecting you with the department head\",\"I will call you back\",\"Please wait in the lobby\",\"The meeting is postponed\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"Ich verbinde = I connect. Sie = you. mit = with. der Abteilungsleiterin = the department head (female).\"}', 20, 'Nghe: Hoi nghi tieng Duc', 'LISTENING_CHOICE', 'e4ce9927-4952-11f1-a796-e00af6a25786'),
('f2002b11-0011-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 6, 15, '{\"question\":\"Hom nay thoi tiet rat dep, ban co muon di cong vien khong? Nghia la _____ bang tieng Anh.\",\r\n  \"options\":[\"The weather is nice today, do you want to go to the park?\",\"Do you have time to visit the museum?\",\"Is it raining today?\",\"Where is the park?\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"Hom nay = today. thoi tiet = weather. rat dep = very nice. di cong vien = go to the park.\"}', 20, 'Nghe: Chuyen giao tiep Tieng Viet', 'LISTENING_CHOICE', 'e4d84836-4952-11f1-a796-e00af6a25786'),
('f2002b12-0012-4c11-9a3c-6fe860ecb615', '2026-05-07 20:00:00.000000', 7, 15, '{\"question\":\"Toi muon dat mot phong don co bancong nhin ra bien. Nghia la _____ bang tieng Anh.\",\r\n  \"options\":[\"I want to book a single room with a balcony overlooking the sea\",\"I need a double room\",\"Do you have a meeting room?\",\"Where is the restaurant?\"],\r\n  \"correctIndex\":0,\r\n  \"explanation\":\"dat = book. phong don = single room. co bancong = with balcony. nhin ra bien = overlooking the sea.\"}', 20, 'Nghe: Dat phong khach san Tieng Viet', 'LISTENING_CHOICE', 'e4d84836-4952-11f1-a796-e00af6a25786'),
('f2105999-223c-4687-a126-3936cd8bb327', '2026-05-07 19:00:00.000000', 5, 10, '{\"question\":\"Tai sao in Vietnamese means _____ in English.\",\"answer\":\"Why\",\"hints\":[\"reason\"],\"explanation\":\"Tai sao = Why.\"}', 15, 'Fill in: _____ = Why', 'FILL_IN_BLANK', 'e4db3481-4952-11f1-a796-e00af6a25786'),
