('fae18705-d3f4-4f6d-ae46-ff076023dd13', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"\\\"Preciso de um médico\\\" trong tiếng Bồ Đào Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Toi can mot bac si\",\"hints\":[\"medical\"],\"explanation\":\"Preciso de = Tôi cần. um médico = Một bác sĩ.\"}', 15, 'Điền: Preciso de um médico = _____', 'FILL_IN_BLANK', 'e4e7dfd5-4952-11f1-a796-e00af6a25786'),
('fb0596e3-e677-432d-837c-f09c3d6ba6f0', '2026-05-07 19:00:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Bo\",\"right\":\"Father\"},{\"left\":\"Me\",\"right\":\"Mother\"},{\"left\":\"Anh\",\"right\":\"Older brother\"},{\"left\":\"Chi\",\"right\":\"Older sister\"}],\"explanation\":\"Vietnamese family words.\"}', 30, 'Match Vietnamese family words', 'MATCHING', 'e4d672c9-4952-11f1-a796-e00af6a25786'),
('fbb2280d-ead8-463d-97c8-97197a5e2b4c', '2026-05-07 19:00:00.000000', 1, 10, '{\"question\":\"Toi ten la _____ in Vietnamese means My name is _____ in English.\",\"options\":[\"Minh\",\"Nguyen\",\"Toi\",\"La\"],\"correctIndex\":0,\"explanation\":\"Toi ten la Minh = My name is Minh.\"}', 20, 'What does ten mean?', 'MULTIPLE_CHOICE', 'e4d94b56-4952-11f1-a796-e00af6a25786'),
('fbb8b214-551c-493b-8e41-677c6248a197', '2026-05-07 19:00:00.000000', 1, 10, '{\"question\":\"Me in Vietnamese means _____ in English.\",\"options\":[\"Father\",\"Mother\",\"Sister\",\"Brother\"],\"correctIndex\":1,\"explanation\":\"Me = Mother. Bo = Father.\"}', 20, 'Me co nghia la gi?', 'MULTIPLE_CHOICE', 'e4db33f7-4952-11f1-a796-e00af6a25786'),
('fbccbed6-c7d6-459f-baf8-d6a5295c0bc0', '2026-05-07 19:00:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Ai\",\"right\":\"Who\"},{\"left\":\"Gi\",\"right\":\"What\"},{\"left\":\"O dau\",\"right\":\"Where\"},{\"left\":\"Nhu the nao\",\"right\":\"How\"}],\"explanation\":\"Vietnamese question words.\"}', 30, 'Match Vietnamese question words', 'MATCHING', 'e4d84d67-4952-11f1-a796-e00af6a25786'),
('fc39fc83-8052-442a-8a60-27b10b6db1fb', '2026-05-07 19:40:00.000000', 2, 10, '{\"question\":\"谢谢 (xièxie) in Mandarin means _____ in English.\",\"answer\":\"Thank you\",\"hints\":[\"gratitude\"],\"explanation\":\"谢谢 = Thank you in Chinese.\"}', 15, 'Fill in: _____ = Thank you', 'FILL_IN_BLANK', 'e4ad4cf0-4952-11f1-a796-e00af6a25786'),
('fcccbb57-2d09-4d6f-828b-47b00c78e465', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"\\\"Dar uma mão\\\" trong tiếng Bồ Đào Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Giup mot tay\",\"hints\":[\"idiom\"],\"explanation\":\"Dar uma mão = Giúp một tay (thành ngữ).\"}', 15, 'Điền: Dar uma mão = _____', 'FILL_IN_BLANK', 'e4e64b9c-4952-11f1-a796-e00af6a25786'),
('fd25d277-5bf7-477e-8c3c-05de1977a364', '2026-05-07 19:40:00.000000', 1, 10, '{\"question\":\"你好 (nǐhǎo) in Mandarin means _____ in English.\",\"options\":[\"Goodbye\",\"Thank you\",\"Hello\",\"Sorry\"],\"correctIndex\":2,\"explanation\":\"你好 means Hello in Chinese.\"}', 20, 'What does 你好 mean?', 'MULTIPLE_CHOICE', 'e4ad4cf0-4952-11f1-a796-e00af6a25786'),
('fd5785f3-a47d-4e12-988c-b431c92cf4aa', '2026-05-07 19:40:00.000000', 2, 10, '{\"question\":\"哥哥 (gēge) in Mandarin means _____ in English.\",\"answer\":\"Older brother\",\"hints\":[\"family\"],\"explanation\":\"哥哥 = Older brother. 弟弟 = Younger brother.\"}', 15, 'Fill in: _____ = Older brother', 'FILL_IN_BLANK', 'e4ab7614-4952-11f1-a796-e00af6a25786'),
('fd70991f-c615-48b3-9887-4655224c80ea', '2026-05-07 19:00:00.000000', 3, 15, '{\"pairs\":[{\"left\":\"Xin chao\",\"right\":\"Hello\"},{\"left\":\"Cam on\",\"right\":\"Thank you\"},{\"left\":\"Xin loi\",\"right\":\"Sorry\"},{\"left\":\"Tam biet\",\"right\":\"Goodbye\"}]}', 30, 'Match Vietnamese phrases', 'MATCHING', 'e4d7650c-4952-11f1-a796-e00af6a25786'),
('fddb71e8-a989-477e-8e1c-bcebaeb194cc', '2026-05-07 20:00:00.000000', 2, 10, '{\"question\":\"Muốn hỏi \\\"Chuyến bay đến Madrid lúc mấy giờ?\\\" bằng tiếng Tây Ban Nha, em nói:\",\"options\":[\"¿A qué hora sale el tren?\",\"¿Cuándo llega el vuelo a Madrid?\",\"¿Dónde está la estación?\",\"¿Cuánto cuesta el billete?\"],\"correctIndex\":1,\"explanation\":\"¿Cuándo llega el vuelo a Madrid? = Chuyến bay đến Madrid khi nào?\"}', 20, 'Hỏi giờ chuyến bay bằng tiếng Tây Ban Nha?', 'MULTIPLE_CHOICE', 'e4d0fce9-4952-11f1-a796-e00af6a25786'),
