('fe31a251-9f0c-4307-b927-25d715000f59', '2026-05-07 20:00:00.000000', 4, 10, '{\"question\":\"\\\"Quisiera\\\" trong tiếng Tây Ban Nha nghĩa là _____ bằng tiếng Việt.\",\"answer\":\"Toi muon\",\"hints\":[\"want\"],\"explanation\":\"Quisiera = Tôi muốn (lịch sự, gợi ý).\"}', 15, 'Điền: Quisiera = _____', 'FILL_IN_BLANK', 'e4d0ef80-4952-11f1-a796-e00af6a25786'),
('fe36e5c9-68f6-4414-80ff-08184c72e727', '2026-05-07 20:00:00.000000', 3, 10, '{\"pairs\":[{\"left\":\"El periodico\",\"right\":\"Ban bao\"},{\"left\":\"La revista\",\"right\":\"Tap chi\"},{\"left\":\"El articulo\",\"right\":\"Bai bao\"},{\"left\":\"El titulo\",\"right\":\"Tieu de\"}],\"explanation\":\"Từ vựng liên quan đến đọc báo và tạp chí.\"}', 30, 'Nối từ vựng đọc báo', 'MATCHING', 'e4d27b27-4952-11f1-a796-e00af6a25786'),
