('e49c2adc-4952-11f1-a796-e00af6a25786', 'PREVIEW', NULL, '<h2>Greetings & Introductions</h2><p>Learn how to greet people and introduce yourself in English.</p>', '2026-05-06 20:52:59.000000', 15, b'1', 1, 'Greetings & Introductions', 'VOCABULARY', '2026-05-06 20:52:59.000000', 'https://www.youtube.com/watch?v=example_en_a1_1', 'e48d6de3-4952-11f1-a796-e00af6a25786'),
('e49c45c1-4952-11f1-a796-e00af6a25786', 'PREVIEW', NULL, '<h2>Numbers & Counting</h2><p>Count from one to one hundred and use numbers in everyday situations.</p>', '2026-05-06 20:52:59.000000', 12, b'1', 2, 'Numbers & Counting', 'VOCABULARY', '2026-05-06 20:52:59.000000', NULL, 'e48d6de3-4952-11f1-a796-e00af6a25786'),
('e49c46c9-4952-11f1-a796-e00af6a25786', 'MONTHLY', NULL, '<h2>Colors & Shapes</h2><p>Describe the world around you with colors and shapes.</p>', '2026-05-06 20:52:59.000000', 10, b'0', 3, 'Colors & Shapes', 'VOCABULARY', '2026-05-06 20:52:59.000000', 'https://www.youtube.com/watch?v=example_en_a1_3', 'e48d6de3-4952-11f1-a796-e00af6a25786'),
('e49c472f-4952-11f1-a796-e00af6a25786', 'MONTHLY', NULL, '<h2>Family Members</h2><p>Learn vocabulary for family members and talk about your family.</p>', '2026-05-06 20:52:59.000000', 15, b'0', 4, 'Family Members', 'VOCABULARY', '2026-05-06 20:52:59.000000', NULL, 'e48d6de3-4952-11f1-a796-e00af6a25786'),
('e49c478b-4952-11f1-a796-e00af6a25786', 'MONTHLY', NULL, '<h2>Days & Months</h2><p>Learn the days of the week and months of the year.</p>', '2026-05-06 20:52:59.000000', 12, b'0', 5, 'Days & Months', 'VOCABULARY', '2026-05-06 20:52:59.000000', 'https://www.youtube.com/watch?v=example_en_a1_5', 'e48d6de3-4952-11f1-a796-e00af6a25786'),
